  sha256 on_system_conditional(
    macos: "5cfe05b54ccc4d2855b83430bc80b2a154027bb4c796dadcfa5b53228929f21e",
    linux: on_arch_conditional(
      arm:   "797c590a3f7bfb8424712673957851cb855f5b83d5245f192a76082654b0c1b8",
